import heapq

def minPath(grid, k):
    N = len(grid)

    # Directions: right, down, left, up
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Initialize a priority queue with the first cell
    pq = [(grid[0][0], 0, 0, k, [grid[0][0]])]

    # Dictionary to keep track of the minimum path for each cell
    min_path = {}

    while pq:
        val, row, col, remaining_steps, path = heapq.heappop(pq)

        if (row, col) in min_path and min_path[(row, col)][3] <= remaining_steps:
            continue

        if remaining_steps == 0:
            return path

        min_path[(row, col)] = (val, row, col, remaining_steps, path)

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            if 0 <= new_row < N and 0 <= new_col < N:
                if (new_row, new_col) not in min_path or min_path[(new_row, new_col)][3] > remaining_steps:
                    heapq.heappush(pq, (val + grid[new_row][new_col], new_row, new_col, remaining_steps - 1, path + [grid[new_row][new_col]]))

    return min_path[(0, 0)][4]
